38	#[comemo::memoize]
39	#[typst_macros::time(name = "eval", span = source.root().span())]
40	pub fn eval(
41	    world: Tracked<dyn World + '_>,
42	    library: &LazyHash<Library>,
43	    traced: Tracked<Traced>,
44	    sink: TrackedMut<Sink>,
45	    route: Tracked<Route>,
46	    source: &Source,
