/// optional.
///
/// See also
/// <https://users.rust-lang.org/t/converting-from-generic-unsized-parameter-to-trait-object/72376>
pub trait AsOutput {
    /// Turns the reference into the trait object.
    fn as_output(&self) -> &dyn Output;
}

